/* Shared read-only History / Revisions browser. */
(function(){
 'use strict';
 const A=ActivityCore,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const names={working:'Working curation',snapshot:'Snapshot annotation',demo:'Synthetic demo',applied:'Applied',recorded:'Judgment recorded',deferred:'Deferred judgment',undone:'Undone',superseded:'Replaced by later judgment',earlier_state:'Earlier membership',removed:'Review removed',finished:'Finished',imported:'Workspace continued',choice_applied:'Saved operation',undo:'Undo operation',finished_event:'Finished workspace',continued_imported_workspace:'Continued workspace',review_saved:'Saved review',review_edited:'Edited review',review_undone:'Undid review',review_imported:'Restored review',latest_review:'Latest saved review',NOT_MERGE:'Keep separate',UNDO:'Undo',FINISH:'Finish',IMPORT:'Continue workspace'};
 function label(v){return names[v]||String(v||'—').replaceAll('_',' ');}
 function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function readWorkspaces(reviewer){return new Promise((resolve,reject)=>{let missing=false;const req=indexedDB.open('spikeagent-working-curation-v1');req.onupgradeneeded=()=>{missing=true;req.transaction.abort();};req.onerror=()=>missing?resolve([]):reject(req.error);req.onsuccess=()=>{const db=req.result;if(!db.objectStoreNames.contains('workspaces')){db.close();resolve([]);return;}const tx=db.transaction('workspaces'),r=tx.objectStore('workspaces').getAll();r.onsuccess=()=>resolve(r.result.filter(s=>s.reviewer===reviewer));r.onerror=()=>reject(r.error);tx.oncomplete=tx.onabort=()=>db.close();};});}
 function mount(root,options){
  let data={history:[],revisions:[],workspaces:[]},view=options.view||'history',filters={},page=0,loading=0,owner='',warnings=[];
  root.classList.add('activity-browser');
  root.innerHTML=`<div class="activity-toolbar"><div class="activity-tabs" role="group" aria-label="Activity view"><button data-activity-view="history">History</button><button data-activity-view="revisions">Revisions</button></div><div class="activity-exports"><button class="button small" data-activity-refresh>Refresh</button><button class="button small" data-activity-export="json">Export filtered JSON</button><button class="button small" data-activity-export="csv">CSV</button></div></div><p class="activity-help">History summarizes saved decisions and operations. Revisions shows each saved change, undo and continuation. Working edits affect a copy; snapshot annotations preserve their recorded grouping.</p><div class="activity-message" role="status"></div><details class="activity-workspaces"><summary>Datasets & workspaces</summary><div class="activity-workspace-list"></div></details><div class="activity-filters"></div><div class="activity-stats"></div><div class="activity-list"></div><div class="activity-pagination"></div>`;
  const $=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)],message=t=>$('.activity-message').textContent=t;
  function save(){try{localStorage.setItem('spikeagent-activity-filters-v1:'+owner,JSON.stringify(filters));}catch{}}
  function visible(){return A.filter(data[view],filters);}
  function select(name,title,values){const keys=[...new Set(values.filter(v=>v!=null&&v!==''))].sort();return `<label>${title}<select data-activity-filter="${name}"><option value="">All</option>${keys.map(v=>`<option value="${esc(v)}" ${filters[name]===v?'selected':''}>${esc(['dataset','workspace','actor','agent'].includes(name)?name==='workspace'?'Workspace '+v.slice(0,8):name==='actor'?options.name(v):name==='agent'?/^Agent_[123]$/.test(v)?v.replace('_',' '):'Saved agent':v:label(v))}</option>`).join('')}</select></label>`;}
  function controls(){
   const rows=[...data.history,...data.revisions];for(const [key,field] of [['dataset','dataset_id'],['workspace','workspace_id'],['kind','kind'],['status','status'],['actor','actor'],['agent','agent']])if(filters[key]&&!rows.some(r=>r[field]===filters[key]))filters[key]='';
   $('.activity-filters').innerHTML='<div class="activity-filter-primary">'+select('kind','Record kind',rows.map(r=>r.kind))+select('dataset','Dataset',rows.map(r=>r.dataset_id))+select('workspace','Workspace',rows.map(r=>r.workspace_id))+select('action','Action',rows.flatMap(r=>[r.action,r.affected_action]))+`<label class="activity-search">Cluster / reason / file<input data-activity-filter="search" value="${esc(filters.search||'')}" placeholder="Cluster ID or text…" type="search"></label><button class="button small" data-activity-reset>Clear filters</button></div><details class="activity-advanced"><summary>More filters</summary><div class="activity-filter-extra">`+select('status','Status',rows.map(r=>r.status))+select('actor','Contributor',rows.map(r=>r.actor))+select('agent','Agent',rows.map(r=>r.agent))+`<label>From (UTC)<input data-activity-filter="from" type="date" value="${esc(filters.from||'')}"></label><label>To (UTC)<input data-activity-filter="to" type="date" value="${esc(filters.to||'')}"></label><label>Group by<select data-activity-filter="group">${[['dataset','Dataset'],['workspace','Workspace'],['day','Date'],['none','No grouping']].map(([v,n])=>`<option value="${v}" ${(filters.group||'dataset')===v?'selected':''}>${n}</option>`).join('')}</select></label></div></details>`;
   $$('[data-activity-filter]').forEach(el=>el.addEventListener(el.tagName==='INPUT'&&el.type==='search'?'input':'change',()=>{filters[el.dataset.activityFilter]=el.value;page=0;save();render();}));
   $('[data-activity-reset]').onclick=()=>{filters={};page=0;save();controls();render();};
  }
  function countTable(row){return row.count_changes.length?`<div class="activity-table-wrap"><table><thead><tr><th>Cluster</th><th>Spikes before</th><th>Spikes after</th><th>Change</th></tr></thead><tbody>${row.count_changes.map(c=>`<tr><th>Cluster ${c.cluster}</th><td>${c.before.toLocaleString()}</td><td>${c.after.toLocaleString()}</td><td>${c.after-c.before>0?'+':''}${(c.after-c.before).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:`<p class="activity-help">${row.kind!=='working'?'Annotation only: spike assignments unchanged.':row.state_before&&row.state_after&&row.state_before===row.state_after?'Spike memberships unchanged.':'No per-cluster spike delta was retained for this older or administrative record.'}</p>`;}
  function value(v){return esc(v==null?'—':typeof v==='string'?v:JSON.stringify(v));}
  function details(row){return `${row.undo_version!=null?`<p>Undo of v${row.undo_version} · ${esc(label(row.affected_action))}</p>`:''}${countTable(row)}${row.changes.length?`<div class="activity-table-wrap"><table><thead><tr><th>Judgment field</th><th>Before</th><th>After</th></tr></thead><tbody>${row.changes.map(c=>`<tr><th>${esc(label(c.field))}</th><td>${value(c.before)}</td><td>${value(c.after)}</td></tr>`).join('')}</tbody></table></div>`:''}<dl class="activity-provenance"><dt>Dataset</dt><dd>${esc(row.dataset_id)}</dd><dt>Workspace / case</dt><dd>${esc(row.workspace_id||row.case_id)}</dd><dt>State before</dt><dd>${esc(row.state_before||'Not retained')}</dd><dt>State after</dt><dd>${esc(row.state_after||'Not retained')}</dd>${row.inherited?'<dt>Contribution</dt><dd>Inherited through an explicitly imported workspace.</dd>':''}</dl>`;}
  function render(){
   $$('[data-activity-view]').forEach(b=>{const active=b.dataset.activityView===view;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
   const activeFilters=['status','actor','agent','from','to'].filter(k=>filters[k]).length;$('.activity-advanced>summary').textContent='More filters'+(activeFilters?' · '+activeFilters+' active':'');
   const rows=visible(),start=page*25,shown=rows.slice(start,start+25);if(start>=rows.length&&page){page=0;render();return;}
   $('.activity-stats').innerHTML=[['Matching records',rows.length],['Datasets',new Set(rows.map(r=>r.dataset_id)).size],['Working edits',rows.filter(r=>r.kind==='working').length],['Snapshot judgments',rows.filter(r=>r.kind!=='working').length]].map(([n,v])=>`<div><span>${n}</span><strong>${v.toLocaleString()}</strong></div>`).join('');
   const groups=new Map();for(const row of shown){const key=filters.group==='none'?'Records':filters.group==='day'?row.timestamp.slice(0,10)||'Date not retained':filters.group==='workspace'?`${row.dataset_id} · ${row.workspace_id?'Workspace '+row.workspace_id.slice(0,8):'Snapshot annotations'}`:row.dataset_id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}
   $('.activity-list').innerHTML=rows.length?[...groups].map(([key,items])=>`<section class="activity-group"><h3>${esc(key)}</h3>${items.map(row=>{const index=shown.indexOf(row);return `<article class="activity-record" data-activity-record="${esc(row.id)}"><div class="activity-record-heading"><strong>${esc(view==='revisions'?label(row.event):label(row.action))}${row.version!=null?' · '+(row.kind==='working'?'v':'revision ')+row.version:''}</strong><span class="activity-status">${esc(label(row.status))}</span></div><p class="activity-object">${row.source!=null?'Cluster '+row.source+(row.target!=null?' vs. Cluster '+row.target:''):row.case_id?esc(row.case_id):'Workspace'}${row.affected_action&&row.action==='UNDO'?' · '+esc(label(row.affected_action)):''}</p><p class="activity-meta"><span class="activity-kind ${row.kind==='working'?'working':'snapshot'}">${esc(label(row.kind))}${row.kind==='working'?'':' · annotations only'}</span> ${esc(row.workspace_label)} · ${esc(options.name(row.actor))}${row.agent?' · '+esc(/^Agent_[123]$/.test(row.agent)?row.agent.replace('_',' '):'Saved agent'):''}${row.inherited?' · Inherited contribution':''} · <time title="${esc(row.timestamp)}">${row.timestamp?esc(new Date(row.timestamp).toLocaleString()):'Time not retained'}</time></p>${row.reason?`<p class="activity-reason">${esc(row.reason)}</p>`:''}${row.note?`<p class="activity-note">${esc(row.note)}</p>`:''}${row.count_changes.length?`<p class="activity-delta">${row.count_changes.slice(0,6).map(c=>`Cluster ${c.cluster}: ${c.before.toLocaleString()} → ${c.after.toLocaleString()}`).join(' · ')}${row.count_changes.length>6?' …':''}</p>`:''}<div class="activity-record-actions"><button class="text-button" data-activity-open="${index}">${row.kind==='working'?'Open current workspace':'Open recorded snapshot'}</button>${options.onUndo&&row.kind!=='working'&&row.event==='latest_review'?`<button class="text-button" data-activity-undo="${index}">Undo latest review</button>`:''}<details ${view==='revisions'?'open':''}><summary>${view==='revisions'?'Changes & provenance':'Show changes & provenance'}</summary>${details(row)}</details></div></article>`;}).join('')}</section>`).join(''):'<div class="empty-state"><h3>No matching saved records.</h3><p>Clear filters or save a decision. Browsing evidence and unsaved drafts do not create revisions.</p></div>';
   $$('[data-activity-open]').forEach(b=>b.onclick=async()=>{try{await options.onOpen(shown[Number(b.dataset.activityOpen)]);}catch(e){message(e.message);}});
   $$('[data-activity-undo]').forEach(b=>b.onclick=async()=>{try{await options.onUndo(shown[Number(b.dataset.activityUndo)]);}catch(e){message(e.message);}});
   $('.activity-pagination').innerHTML=`<button class="button small" data-page="prev" ${page===0?'disabled':''}>Previous</button><span>${rows.length?start+1:0}–${Math.min(start+25,rows.length)} of ${rows.length}</span><button class="button small" data-page="next" ${start+25>=rows.length?'disabled':''}>Next</button>`;
   $$('[data-page]').forEach(b=>b.onclick=()=>{page+=b.dataset.page==='next'?1:-1;render();root.scrollIntoView({block:'start'});});
  }
  function workspaces(){
   $('.activity-workspace-list').innerHTML=data.workspaces.length?data.workspaces.map(s=>`<div><strong>${esc(s.recording_id)}</strong><p>${esc(s.dataset_id)} · Workspace ${esc(s.id.slice(0,8))} · v${s.version} · ${s.clusters} current clusters · ${s.pending} need review · ${s.complete?'Finished':'In progress'}</p>${s.parent?`<p>Continued from workspace ${esc(s.parent.workspace_id)} · v${s.parent.version} · ${esc(options.name(s.parent.previous_reviewer))}</p>`:''}<button class="text-button" data-workspace-open="${esc(s.id)}">Open current workspace</button></div>`).join(''):'<p class="activity-help">No working copies for this reviewer in this browser. Snapshot reviews are listed separately below.</p>';
   $$('[data-workspace-open]').forEach(b=>b.onclick=async()=>{try{await options.onOpen({kind:'working',workspace_id:b.dataset.workspaceOpen});}catch(e){message(e.message);}});
  }
  async function refresh(nextView=view){view=nextView;const token=++loading,identity=options.owner();message('Loading this reviewer’s saved records…');$('.activity-list').replaceChildren();
   try{const result=await options.load();if(token!==loading||identity!==options.owner())return;if(owner!==identity){owner=identity;try{filters=JSON.parse(localStorage.getItem('spikeagent-activity-filters-v1:'+owner)||'{}')||{};}catch{filters={};}if(typeof filters!=='object'||Array.isArray(filters))filters={};}
    data=result;warnings=result.warnings||[];page=0;controls();workspaces();render();message(warnings.join(' ')||'Reviewer: '+options.name(owner)+'. Current reviewer only. Working copies stay in this browser; annotation storage follows the selected site. Filtered exports are reports; use Export workspace for a resumable backup.');
   }catch(e){message('Could not load activity: '+e.message);}
  }
  $$('[data-activity-view]').forEach(b=>b.onclick=()=>{view=b.dataset.activityView;page=0;render();options.onView?.(view);});$('[data-activity-refresh]').onclick=()=>refresh();
  $$('[data-activity-export]').forEach(b=>b.onclick=()=>{const rows=visible(),json=b.dataset.activityExport==='json';download(json?JSON.stringify({schema:'spikeagent-activity-report-v1',reviewer_id:owner,view,filters,exported_at:new Date().toISOString(),records:rows,workspaces:data.workspaces.filter(s=>rows.some(r=>r.workspace_id===s.id))},null,2):'\ufeff'+A.csv(rows),'spikeagent-'+view+'-filtered.'+(json?'json':'csv'),json?'application/json':'text/csv;charset=utf-8');});
  return {refresh,setView(v){view=v;page=0;render();},get data(){return data;}};
 }
 window.ActivityUI={mount,readWorkspaces};
})();
